<script setup>
import {reactive,ref,onMounted,onBeforeUnmount} from 'vue'
import {api} from '../api'
const props=defineProps({title:String,description:String,fields:Array,initial:Object,submit:Function,button:{default:'确认提交'}})
const emit=defineEmits(['close','done'])
const data=reactive({...props.initial}),error=ref(''),busy=ref(false),uploads=reactive({}),dialog=ref(null)
props.fields.forEach(f=>{if(data[f.key]===undefined)data[f.key]=f.default??(f.type==='checkbox'?false:f.type==='file'?[]:'')})
let previous
onMounted(()=>{previous=document.activeElement;document.body.classList.add('modal-open');dialog.value?.querySelector('input,select,textarea,button')?.focus()})
onBeforeUnmount(()=>{document.body.classList.remove('modal-open');previous?.focus?.()})
function keydown(e){if(e.key==='Escape'&&!busy.value)emit('close');if(e.key==='Tab'){const nodes=[...dialog.value.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')];if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0]?.focus()}}}
async function upload(e,field){error.value='';busy.value=true;try{let selected=[...e.target.files];if(selected.length>10)throw Error('一次最多上传10个文件');let added=[];for(const file of selected){if(file.size>10*1024*1024)throw Error(file.name+' 超过10MB');const body=new FormData();body.append('file',file);added.push(await api('/attachments',body))}uploads[field.key]=[...(uploads[field.key]||[]),...added];data[field.key]=uploads[field.key].map(f=>f.id)}catch(e){error.value=e.message}finally{busy.value=false;e.target.value=''}}
async function send(){error.value='';busy.value=true;try{const result=await props.submit({...data});emit('done',result)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="modal-backdrop" @click.self="!busy&&emit('close')"><section ref="dialog" class="dialog" role="dialog" aria-modal="true" aria-labelledby="form-title" @keydown="keydown"><header><div><p class="eyebrow">业务办理</p><h2 id="form-title">{{title}}</h2></div><button class="icon-button" aria-label="关闭窗口" :disabled="busy" @click="emit('close')">×</button></header><p v-if="description" class="dialog-description">{{description}}</p><form @submit.prevent="send"><div class="form-grid"><label v-for="f in fields" :key="f.key" :class="['field',{'full':f.wide||['textarea','file'].includes(f.type),'check-field':f.type==='checkbox'}]"><span>{{f.label}}<i v-if="f.required"> *</i></span><textarea v-if="f.type==='textarea'" v-model="data[f.key]" :required="f.required" :maxlength="f.max||2000" rows="4" :placeholder="f.placeholder"></textarea><select v-else-if="f.type==='select'" v-model="data[f.key]" :required="f.required"><option value="" disabled>请选择</option><option v-for="o in f.options" :key="o.value??o" :value="o.value??o">{{o.label??o}}</option></select><input v-else-if="f.type==='checkbox'" type="checkbox" v-model="data[f.key]"><template v-else-if="f.type==='file'"><input type="file" multiple accept=".png,.jpg,.jpeg,.pdf,.docx,.txt" :disabled="busy" @change="upload($event,f)"><small>PNG / JPG / PDF / DOCX / TXT，单文件不超过10MB</small><div v-for="(file,i) in uploads[f.key]||[]" class="upload-item">{{file.filename}}<button type="button" @click="uploads[f.key].splice(i,1);data[f.key]=uploads[f.key].map(x=>x.id)">移除</button></div></template><input v-else v-model="data[f.key]" :type="f.type||'text'" :required="f.required" :step="f.step||'any'" :min="f.min" :max="f.max" :maxlength="f.maxlength||500" :placeholder="f.placeholder" :autocomplete="f.type==='password'?'new-password':'off'"><small v-if="f.help">{{f.help}}</small></label></div><div v-if="error" class="error-box" role="alert">{{error}}</div><footer><button type="button" :disabled="busy" @click="emit('close')">取消</button><button class="primary" :disabled="busy">{{busy?'正在处理…':button}}</button></footer></form></section></div></template>
